func (t Packet) WriteTo(w io.Writer) (totalBytes int64, err error) {
	var bytesWritten int64

	defer func() {
		log.Printf("[ChatMessage.WriteTo] totalBytes: %d err: %#v", totalBytes, err)
	}()
	bytesWritten, err = t.Name.WriteTo(w)
	totalBytes += bytesWritten
	if err != nil {
		return totalBytes, err
	}

	// Switch field Params based on name
	if t.Params != nil {
		// Write switch field value if it implements WriteTo
		if writer, ok := t.Params.(interface {
			WriteTo(io.Writer) (int64, error)
		}); ok {
			bytesWritten, err = writer.WriteTo(w)
			totalBytes += bytesWritten
			if err != nil {
				return totalBytes, err
			}
		} else {
			// Not a void case and doesn't implement WriteTo
			return totalBytes, fmt.Errorf("switch field Params value does not implement WriteTo: %T", t.Params)
		}
	}

	return totalBytes, nil
}

